Variables (t : Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet) (LBX : list (Z * Z)) (cr : credit)
          (sp r fb cat : Z) (p : list Z) (X : st).
Variables (mo dn dp qc de rem tg vb vk : Z) (tb : PM.vstr) (stk : list PM.pstate) (str : PM.vstr) (g eg sst : Z)
          (en : PEC.enc) (k : PESK.sink) (e : bool).
Let s : PM.pst := PM.PST mo dn dp (PM.SRC qc de rem) tb tg vb vk stk.
Let sm : PM.strm := PM.STRM g eg sst.
Hypothesis HH : hi_heap HI (PEC.owned s en k ++ LBX) cr M (m_vmmaps model).
Hypothesis MOK : PMSP.model_ok model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSP.entry CAD L R M sp r 8.
Hypothesis FOK : PMSP.frame_ok CAD L sp fb.
Hypothesis A10 : getr R 10%bv = Z_to_bv 64 (fb + 40).
Hypothesis A11 : getr R 11%bv = Z_to_bv 64 (fb + 432).
Hypothesis A13 : getr R 13%bv = Z_to_bv 64 (fb + 8).
Hypothesis Ht : 0 <= t < 256.
Hypothesis A12 : getr R 12%bv = Z_to_bv 64 t.
Hypothesis CPRE : PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M fb p X s str sm en k e cat.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis POK : PECS.payload_ok p.
Hypothesis MP : PECS.mp_rv t p X.
Hypothesis NB : s_bad (r_value p t X) = false.
Hypothesis HB : PESK.sp_hb P (s_hi (r_value p t X)).
Hypothesis CRED : PMSP.credit_le (PEC.pot_all L P s en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model)
            (s' : PM.pst) (sm' : PM.strm) (en' : PEC.enc) (k' : PESK.sink) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M' fb p (r_value p t X) s' str sm' en' k' e' cat ->
        PMSP.src_step (PM.p_src s) (PM.p_src s') sm sm' -> (e = true -> e' = true) ->
        L5C.hpres L LBX sp (PMSP.pm_scr 8) (PEC.W_crun CAD EE fb) M M' ->
        PMSP.credit_keep cr cr' (PEC.pot_all L P s en k) (PEC.pot_all L P s' en' k') ->
        model_but_vm model model' -> hi_heap HI (PEC.owned s' en' k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

(* [comment removed for export] *)
Definition CSK : list nat := [3; 4; 21; 22; 23; 24; 25; 26; 27]%nat.
Definition csk (Ri : bvmap 5 word) : Prop := forall j, In j CSK -> getr Ri (PMK.reg j) = getr R (PMK.reg j).

(* [comment removed for export] *)
Definition mid (fxi : FPState) (Ri : bvmap 5 word) (Mi : word -> option byte) (mdi : Model) (cri : credit)
           (si : PM.pst) (smi : PM.strm) (eni : PEC.enc) (ki : PESK.sink) (ei : bool) (Xi : st) : Prop :=
  getr Ri (PMK.reg 2) = Z_to_bv 64 (sp - 80) /\ getr Ri (PMK.reg 8) = Z_to_bv 64 (fb + 40) /\ getr Ri (PMK.reg 9) = Z_to_bv 64 (fb + 8)
  /\ getr Ri (PMK.reg 18) = Z_to_bv 64 (fb + 432) /\ csk Ri
  /\ L5.u64_at RSEGS Mi (sp - 8) (bv_unsigned (getr R (PMK.reg 1))) /\ L5.u64_at RSEGS Mi (sp - 16) (bv_unsigned (getr R (PMK.reg 8)))
  /\ L5.u64_at RSEGS Mi (sp - 24) (bv_unsigned (getr R (PMK.reg 9))) /\ L5.u64_at RSEGS Mi (sp - 32) (bv_unsigned (getr R (PMK.reg 18)))
  /\ L5.u64_at RSEGS Mi (sp - 40) (bv_unsigned (getr R (PMK.reg 19))) /\ L5.u64_at RSEGS Mi (sp - 48) (bv_unsigned (getr R (PMK.reg 20)))
  /\ L5C.stk (hl_sptop L) Mi sp 28672 /\ model_but_vm model mdi /\ PMSP.model_ok mdi
  /\ hi_heap HI (PEC.owned si eni ki ++ LBX) cri Mi (m_vmmaps mdi)
  /\ PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P Mi fb p Xi si str smi eni ki ei cat
  /\ PMSP.src_step (PM.p_src s) (PM.p_src si) sm smi /\ (e = true -> ei = true)
  /\ PMK.ek L LBX sp 28672 (PEC.W_crun CAD EE fb) M Mi /\ PMK.dk L LBX sp 28672 M Mi
  /\ PMSP.credit_keep cr cri (PEC.pot_all L P s en k) (PEC.pot_all L P si eni ki).

(* [comment removed for export] *)
Definition facts : Prop :=
  L5.ra_ok r /\ getr R (PMK.reg 1) = Z_to_bv 64 r /\ getr R (PMK.reg 2) = Z_to_bv 64 sp
  /\ sp mod 16 = 0 /\ hl_sptop L - 2 ^ 23 + 28672 <= sp /\ sp <= hl_sptop L /\ (0x7fff80000000 <= hl_sptop L <= 2 ^ 47)
  /\ sp <= fb /\ fb + 832 <= hl_sptop L /\ fb mod 16 = 0.
