Lemma call_valid (pp n ra : Z) (l : list Z) fxi Ri Mi mdi cri si smi eni ki ei Y :
  mid fxi Ri Mi mdi cri si smi eni ki ei Y ->
  getr Ri (PMK.reg 1) = Z_to_bv 64 ra -> L5.ra_ok ra -> getr Ri (PMK.reg 10) = Z_to_bv 64 pp -> getr Ri (PMK.reg 11) = Z_to_bv 64 n ->
  0 <= n < 2 ^ 26 -> 0 <= pp -> (n = 0 \/ 0 < pp) -> pp + n <= 2 ^ 47 -> L5.defined Mi pp n -> (sp - 80 <= pp \/ pp + n <= sp - 80 - 12288) ->
  L5.bytes_at RSEGS Mi pp l -> Z.of_nat (length l) = n -> Forall (fun b => 0 <= b < 256) l ->
  (forall fx2 R2 M2 v, regs_preserved Ri R2 -> getr R2 (PMK.reg 11) = Z_to_bv 64 v -> 0 <= v < 7 -> (v = 0 <-> UbjRef.utf8_valid l = true) ->
      mem_grows Mi M2 -> (forall i, 0 <= i < 2 ^ 64 -> ~ (sp - 80 - 12288 <= i < sp - 80) -> M2 (Z_to_bv 64 i) = Mi (Z_to_bv 64 i)) ->
      mid fx2 R2 M2 mdi cri si smi eni ki ei Y -> srealizes RSEGS SCFG (PMSP.cfg RSEGS R2 ra M2 mdi) K) ->
  srealizes RSEGS SCFG (PMSP.cfg RSEGS Ri 0x3ad4c Mi mdi) K.
Proof.
